#!/usr/bin/env python3
"""CHANGELOG.md (shown as changelog.html): everything that happened, with emojis. Timeline from assets/changelog.json (hand-written, grouped in rounds),
export versions from assets/exports.json, the decision log from assets/edl_decisions.json, results from assets/okr_result.json, commits from git.
Run: python3 -I scripts/build_changelog.py   (reusable: the data files are the only per-video part)"""
import json, pathlib, subprocess
ROOT = pathlib.Path(__file__).resolve().parent.parent
J = lambda p, d=None: json.load(open(ROOT / p)) if (ROOT / p).exists() else d
P, rounds, reg, dec, okr = J("remotion/src/project.json", {}), J("assets/changelog.json", []), J("assets/exports.json", []), J("assets/edl_decisions.json", []), J("assets/okr_result.json")
L = ["---\npublished: false\n---", f"# 🗒️ Changelog: everything that happened", "",
     "Legend: 🚀 start · 🎬 video edit · 🧩 site or tool · 🐛 bug found and fixed · 🔒 privacy · 🔊 audio · ♻️ reuse and kit · ☁️ publish and backup · 🧪 tests · 🛑 blocked by the permission system · 📈 measured · 📝 owner's notes · 🧠 decision", ""]
if reg:
    L += ["## 🎞️ Export versions", "", "| Version | Rendered | Length | Size | What changed |", "|---|---|---|---|---|"]
    for e in reversed(reg): L.append(f"| **v{e['v']}** {'(latest)' if e['v'] == max(x['v'] for x in reg) else ''}{'' if e.get('file') else ' (not kept)'} | {e.get('rendered', '')} | {e.get('seconds', '')} s | {e.get('size_mb', '')} MB | {e.get('notes', '')} |")
    L.append("")
if okr: L += ["## 📈 Where it stands", "", f"- 🎯 Value-recognition score **{okr['score']} / 100**, grade {okr['grade']}; key results: ✅ {okr['kr']['met']} met · 🟡 {okr['kr']['almost']} almost · ❌ {okr['kr']['missed']} missed · ⏳ {okr['kr']['open']} open (see the Pre-prod page)", ""]
for r in reversed(rounds):
    L += [f"## {r['round']}", f"*{r.get('when', '')}*", ""] + [f"- {i[0]} **{i[1]}**: {i[2]}" for i in r["items"]] + [""]
if dec:
    L += ["## 🧠 Decision log: every owner note and how it was handled", "", "| # | In | Said | Decision |", "|---|---|---|---|"]
    for d in reversed(dec): L.append(f"| {d['id']} | {d.get('in', '')} | {d['said']} | {d['decision']} |")
    L.append("")
try:
    g = subprocess.check_output(["git", "-C", str(ROOT), "log", "--pretty=format:%h|%ad|%s", "--date=format:%Y-%m-%d %H:%M", "-n", "40"], text=True, stderr=subprocess.DEVNULL).splitlines()
    if g: L += ["## ☁️ Commits (from git)", "", "| Commit | When | Message |", "|---|---|---|"] + [f"| `{x.split('|')[0]}` | {x.split('|')[1]} | {x.split('|', 2)[2]} |" for x in g] + [""]
except Exception: pass
L += ["---", "*Generated by `scripts/build_changelog.py`. Add events to `assets/changelog.json` as you work; the tables update themselves.*"]
(ROOT / "CHANGELOG.md").write_text("\n".join(L)); print(f"CHANGELOG.md: {len(rounds)} rounds, {len(reg)} versions, {len(dec)} decisions")
